{
  "findings": [
    {
      "check_id": "CKV_AZURE_10",
      "title": "Function App should have HTTPS Only enabled",
      "resource": "azurerm_function_app.changeme_simple_function_app",
      "severity": "HIGH",
      "explanation": "The Function App does not enforce HTTPS-only traffic, allowing potential interception of data via unencrypted HTTP connections."
    },
    {
      "check_id": "CKV_AZURE_11",
      "title": "Function App should use a minimum TLS version of 1.2",
      "resource": "azurerm_function_app.changeme_simple_function_app",
      "severity": "MEDIUM",
      "explanation": "The Function App does not explicitly set the minimum TLS version, potentially allowing older, insecure protocols like TLS 1.0 or 1.1."
    }
  ],
  "patched_code": "resource \"azurerm_function_app\" \"changeme_simple_function_app\" {\n  name                       = \"changeme-simple-function-app-name\"\n  location                   = azurerm_resource_group.changeme_simple_function_app_resource_group.location\n  resource_group_name        = azurerm_resource_group.changeme_simple_function_app_resource_group.name\n  app_service_plan_id        = azurerm_app_service_plan.changeme_simple_function_app_app_service_plan.id\n  storage_account_name       = azurerm_storage_account.changeme_simple_function_app_storage_account.name\n  storage_account_access_key = azurerm_storage_account.changeme_simple_function_app_storage_account.primary_access_key\n  https_only                 = true\n  site_config {\n    min_tls_version = \"1.2\"\n  }\n}",
  "fix_summary": "Added 'https_only = true' to enforce encrypted traffic and configured 'site_config' with 'min_tls_version = \"1.2\"' to disable insecure TLS protocols."
}
